(()=>{'use strict';
const main=document.getElementById('circleMain');if(!main)return;const PROFILE='safariCircleProfile',SETTINGS='safariCircleSettings',FOLLOWING='safariCircleFollowing',SAVED='safariCircleSavedPosts',BLOCKED='safariCircleBlocked',ALERTS='safariCircleAlerts',THREADS='safariCircleThreads';
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},write=(k,v)=>localStorage.setItem(k,JSON.stringify(v)),profile=()=>read(PROFILE,null),initials=n=>String(n||'Safari member').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
async function api(path,options={}){const response=await fetch(`/api/circle${path}`,{credentials:'include',headers:{Accept:'application/json','Content-Type':'application/json',...(options.headers||{})},...options});let body={};try{body=await response.json()}catch{}if(!response.ok)throw new Error(body.message||'Circle could not connect.');return body}
const memberResults=document.getElementById('circleMemberResults'),memberSearch=document.getElementById('circleMemberSearch'),roleFilter=document.getElementById('circleMemberRole');let memberTimer;
function memberCard(m){const following=read(FOLLOWING,[]).includes(m.id);return `<article class="circle-member-card" data-member-id="${safe(m.id)}"><span class="circle-member-avatar">${safe(initials(m.displayName))}</span><div><h3>${safe(m.displayName)}</h3><small>${safe(m.handle?'@'+m.handle:'')} ${m.verified?'· ✓ Verified contact':''}</small><p>${safe([m.role,m.homeCountry].filter(Boolean).join(' · '))}</p></div><div class="circle-member-actions"><button type="button" class="primary" data-member-follow>${following?'Following':'Follow'}</button><button type="button" data-member-message>Message</button><button type="button" data-member-more aria-label="More actions">•••</button></div></article>`}
async function discover(){const query=memberSearch.value.trim(),role=roleFilter.value;memberResults.innerHTML='<div class="circle-empty"><strong>Finding your community…</strong></div>';try{const data=await api(`/members?query=${encodeURIComponent(query)}&role=${encodeURIComponent(role)}`),blocked=new Set(read(BLOCKED,[])),members=(data.members||[]).filter(m=>!blocked.has(m.id));memberResults.innerHTML=members.length?members.map(memberCard).join(''):'<div class="circle-empty"><strong>No members found.</strong><p>Try another name, country, role or safari interest.</p></div>'}catch(error){memberResults.innerHTML=`<div class="circle-empty"><strong>Community directory unavailable.</strong><p>${safe(error.message)}</p><button type="button" data-retry-members>Retry</button></div>`}}
memberSearch.addEventListener('input',()=>{clearTimeout(memberTimer);memberTimer=setTimeout(discover,350)});roleFilter.addEventListener('change',discover);memberResults.addEventListener('click',async e=>{if(e.target.closest('[data-retry-members]')){discover();return}const card=e.target.closest('[data-member-id]');if(!card)return;const id=card.dataset.memberId;if(e.target.closest('[data-member-follow]')){const following=new Set(read(FOLLOWING,[])),willFollow=!following.has(id);try{await api(`/members/${encodeURIComponent(id)}/follow`,{method:willFollow?'POST':'DELETE'});willFollow?following.add(id):following.delete(id);write(FOLLOWING,[...following]);e.target.closest('[data-member-follow]').textContent=willFollow?'Following':'Follow'}catch(error){showToast(error.message)}}else if(e.target.closest('[data-member-message]'))openNewMessage(id,card.querySelector('h3').textContent);else if(e.target.closest('[data-member-more]'))openSafetyModal('member',id)});
const threadList=document.getElementById('circleConversationList'),conversation=document.getElementById('circleConversation');let activeThread='';
function localThreads(){const value=read(THREADS,[]);return Array.isArray(value)?value:[]}
function renderThreads(){const threads=localThreads();threadList.innerHTML=threads.length?threads.map(t=>`<button class="circle-conversation-item ${t.id===activeThread?'selected':''}" data-thread="${safe(t.id)}"><span class="circle-member-avatar">${safe(initials(t.name))}</span><span><strong>${safe(t.name)}</strong><small>${safe(t.messages?.at(-1)?.text||'Start a conversation')}</small></span></button>`).join(''):'<div class="circle-empty"><strong>No conversations yet.</strong></div>';updateCounts()}
function renderConversation(){const thread=localThreads().find(t=>t.id===activeThread);if(!thread){conversation.innerHTML='<div class="circle-empty"><strong>Select a conversation.</strong><p>Share plans and field knowledge privately.</p></div>';return}conversation.innerHTML=`<header class="circle-chat-head"><div><strong>${safe(thread.name)}</strong><small>${thread.online?'Online':'Safari Circle member'}</small></div><button type="button" data-conversation-safety>Safety</button></header><div class="circle-chat-messages">${(thread.messages||[]).map(m=>`<div class="circle-chat-message ${m.mine?'mine':''}">${safe(m.text)}<small>${safe(new Date(m.createdAt).toLocaleString())}</small></div>`).join('')}</div><form class="circle-message-form"><input required maxlength="1200" placeholder="Write a message" aria-label="Message ${safe(thread.name)}"><button>Send</button></form>`;conversation.querySelector('.circle-chat-messages').scrollTop=999999}
function openNewMessage(memberId,name){const threads=localThreads();let thread=threads.find(t=>t.memberId===memberId);if(!thread){thread={id:crypto.randomUUID?.()||String(Date.now()),memberId,name,messages:[],unread:0};threads.unshift(thread);write(THREADS,threads)}activeThread=thread.id;renderThreads();renderConversation();document.querySelector('[data-circle-tab="messages"]')?.click()}
threadList.addEventListener('click',e=>{const button=e.target.closest('[data-thread]');if(!button)return;activeThread=button.dataset.thread;const threads=localThreads(),thread=threads.find(t=>t.id===activeThread);if(thread)thread.unread=0;write(THREADS,threads);renderThreads();renderConversation()});conversation.addEventListener('submit',async e=>{const form=e.target.closest('.circle-message-form');if(!form)return;e.preventDefault();const input=form.querySelector('input'),text=input.value.trim();if(!text)return;const threads=localThreads(),thread=threads.find(t=>t.id===activeThread),message={id:crypto.randomUUID?.()||String(Date.now()),text:text.slice(0,1200),mine:true,createdAt:new Date().toISOString()};thread.messages.push(message);write(THREADS,threads);input.value='';renderThreads();renderConversation();try{await api(`/threads/${encodeURIComponent(thread.id)}/messages`,{method:'POST',body:JSON.stringify({text:message.text,recipientId:thread.memberId})})}catch{showToast('Message saved. It will send when Circle reconnects.')}});conversation.addEventListener('click',e=>{if(e.target.closest('[data-conversation-safety]')){const t=localThreads().find(x=>x.id===activeThread);openSafetyModal('member',t?.memberId)}});document.getElementById('circleNewMessage').addEventListener('click',()=>{document.querySelector('[data-circle-tab="network"]')?.click();memberSearch.focus()});
const alertsBox=document.getElementById('circleNotificationList');let alertFilter='all';function alerts(){const a=read(ALERTS,[]);return Array.isArray(a)?a:[]}function renderAlerts(){const rows=alerts().filter(a=>alertFilter==='all'||a.kind===alertFilter);alertsBox.innerHTML=rows.length?rows.map(a=>`<button class="circle-notification ${a.read?'':'unread'}" data-alert="${safe(a.id)}"><i></i><p>${safe(a.text)}<small>${safe(new Date(a.createdAt).toLocaleString())}</small></p><span>›</span></button>`).join(''):'<div class="circle-empty"><strong>You are all caught up.</strong><p>New reactions, comments, follows and messages will appear here.</p></div>';updateCounts()}document.getElementById('circleAlertFilters').addEventListener('click',e=>{const b=e.target.closest('[data-alert-filter]');if(!b)return;alertFilter=b.dataset.alertFilter;document.querySelectorAll('[data-alert-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderAlerts()});alertsBox.addEventListener('click',e=>{const b=e.target.closest('[data-alert]');if(!b)return;const rows=alerts(),a=rows.find(x=>x.id===b.dataset.alert);if(a)a.read=true;write(ALERTS,rows);renderAlerts()});document.getElementById('circleMarkAlertsRead').addEventListener('click',()=>{write(ALERTS,alerts().map(a=>({...a,read:true})));renderAlerts()});
function updateCounts(){const unreadMessages=localThreads().reduce((n,t)=>n+(t.unread||0),0),unreadAlerts=alerts().filter(a=>!a.read).length;for(const [id,n] of [['circleMessageCount',unreadMessages],['circleNotificationCount',unreadAlerts]]){const el=document.getElementById(id);el.hidden=!n;el.textContent=n>99?'99+':n}}
const defaults={profileVisibility:'public',messagePrivacy:'members',protectLocations:true,notifications:true};function loadSettings(){const s={...defaults,...read(SETTINGS,{})};document.getElementById('circleProfileVisibility').value=s.profileVisibility;document.getElementById('circleMessagePrivacy').value=s.messagePrivacy;document.getElementById('circleSensitiveDefault').checked=s.protectLocations;document.getElementById('circleNotificationPush').checked=s.notifications}function saveSettings(){const s={profileVisibility:document.getElementById('circleProfileVisibility').value,messagePrivacy:document.getElementById('circleMessagePrivacy').value,protectLocations:document.getElementById('circleSensitiveDefault').checked,notifications:document.getElementById('circleNotificationPush').checked};write(SETTINGS,s);document.getElementById('circleSensitive').checked=s.protectLocations;const status=document.getElementById('circleSettingsStatus');status.textContent='Circle preferences saved.';api('/me/settings',{method:'PUT',body:JSON.stringify(s)}).catch(()=>{});setTimeout(()=>status.textContent='',2000)}document.querySelectorAll('#circleProfileVisibility,#circleMessagePrivacy,#circleSensitiveDefault,#circleNotificationPush').forEach(el=>el.addEventListener('change',saveSettings));
function ensureModal(){let d=document.getElementById('circleActionDialog');if(d)return d;d=document.createElement('dialog');d.id='circleActionDialog';d.className='circle-modal';document.body.append(d);d.addEventListener('click',e=>{if(e.target.closest('.circle-modal-close'))d.close()});return d}function openSafetyModal(type,id){const d=ensureModal();d.innerHTML=`<div class="circle-modal-inner"><button class="circle-modal-close" aria-label="Close">×</button><p class="eyebrow dark">COMMUNITY SAFETY</p><h2>Protect your Circle</h2><form id="circleSafetyForm"><input type="hidden" name="target" value="${safe(id)}"><label>Action<select name="action"><option value="report">Report to moderators</option><option value="block">Block this account</option></select></label><label>Reason<select name="reason"><option>Harassment or abuse</option><option>False or dangerous field information</option><option>Sensitive wildlife location</option><option>Spam or fraud</option><option>Impersonation</option><option>Other</option></select></label><label>Details<textarea name="details" maxlength="800" placeholder="Give moderators enough context to review this safely"></textarea></label><button>Submit</button><p aria-live="polite"></p></form></div>`;d.showModal();d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target),action=form.get('action'),target=form.get('target');if(action==='block'){const blocked=new Set(read(BLOCKED,[]));blocked.add(target);write(BLOCKED,[...blocked]);try{await api(`/members/${encodeURIComponent(target)}/block`,{method:'POST'})}catch{}d.close();discover();showToast('Account blocked.')}else{const status=e.target.querySelector('p');status.textContent='Sending report…';try{await api('/reports',{method:'POST',body:JSON.stringify({targetType:type,targetId:target,reason:form.get('reason'),details:String(form.get('details')).slice(0,800)})});status.textContent='Report sent to the moderation team.';setTimeout(()=>d.close(),900)}catch(error){status.textContent=error.message}}})}
function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2500)}
document.getElementById('circleBlockedPeople').addEventListener('click',()=>{const d=ensureModal(),blocked=read(BLOCKED,[]);d.innerHTML=`<div class="circle-modal-inner"><button class="circle-modal-close" aria-label="Close">×</button><p class="eyebrow dark">PRIVACY</p><h2>Blocked accounts</h2>${blocked.length?`<p>${blocked.length} ${blocked.length===1?'account is':'accounts are'} blocked. Blocked members cannot find, follow or message you.</p><button type="button" id="circleClearBlocked">Review and clear local block list</button>`:'<div class="circle-empty"><strong>No blocked accounts.</strong></div>'}</div>`;d.showModal();d.querySelector('#circleClearBlocked')?.addEventListener('click',()=>{if(confirm('Unblock all accounts on this device?')){write(BLOCKED,[]);d.close()}})});document.getElementById('circleCommunityGuidelines').addEventListener('click',()=>{const d=ensureModal();d.innerHTML='<div class="circle-modal-inner"><button class="circle-modal-close" aria-label="Close">×</button><p class="eyebrow dark">COMMUNITY GUIDELINES</p><h2>Protect people and wildlife.</h2><p>Be respectful, credit creative work, do not promote wildlife harassment, trafficking or unsafe conduct, and conceal sensitive species locations. Do not publish another person’s private information. Reports are reviewed in context and serious or repeated violations can restrict an account.</p></div>';d.showModal()});document.getElementById('circleViewSaved').addEventListener('click',()=>{document.querySelector('[data-circle-tab="feed"]')?.click();showToast(`${read(SAVED,[]).length} saved posts`)});
const feed=document.getElementById('circleFeed'),observer=new MutationObserver(()=>feed.querySelectorAll('.circle-post').forEach(card=>{if(card.querySelector('.circle-action-menu'))return;const head=card.querySelector('.circle-post-head');if(!head)return;head.insertAdjacentHTML('beforeend',`<span class="circle-action-menu"><button type="button" data-post-menu aria-label="Post actions">•••</button><span class="circle-post-menu" hidden><button type="button" data-save-community-post>Save post</button><button type="button" data-report-community-post>Report post</button></span></span>`)}));observer.observe(feed,{childList:true,subtree:true});feed.append(document.createTextNode(''));feed.lastChild.remove();feed.addEventListener('click',e=>{const card=e.target.closest('[data-circle-post]');if(!card)return;const menu=card.querySelector('.circle-post-menu');if(e.target.closest('[data-post-menu]')){menu.hidden=!menu.hidden;e.stopPropagation()}else if(e.target.closest('[data-save-community-post]')){const saved=new Set(read(SAVED,[]));saved.has(card.dataset.circlePost)?saved.delete(card.dataset.circlePost):saved.add(card.dataset.circlePost);write(SAVED,[...saved]);menu.hidden=true;showToast(saved.has(card.dataset.circlePost)?'Post saved.':'Post removed from saved.')}else if(e.target.closest('[data-report-community-post]'))openSafetyModal('post',card.dataset.circlePost)},true);
document.querySelectorAll('[data-circle-tab]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.circleTab==='network'&&!memberSearch.value)discover();if(button.dataset.circleTab==='messages'){renderThreads();renderConversation()}if(button.dataset.circleTab==='notifications')renderAlerts();if(button.dataset.circleTab==='profile')loadSettings()}));loadSettings();renderThreads();renderAlerts();
})();
